// handover_card / handover_item row-level security and integrity — generated by `pnpm gen:migration`
// (02-architecture §4, 04-testing §3); SOP-DEL-01 cases added (E2 AC1, AC7).
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, expect, inject, it } from 'vitest';
import { createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  client,
  createDatabase,
  eq,
  handoverCard,
  handoverItem,
  inActorTransaction,
  migrateUp,
  site,
  type Database,
  type DbActor,
} from '../index.ts';

const clientA = randomUUID();
const clientB = randomUUID();
const siteA = randomUUID();
const siteB = randomUUID();
const cardA = randomUUID();
const staff: DbActor = { id: randomUUID(), kind: 'staff', clientIds: [] };
const userOfA: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientA] };
const partnerOfA: DbActor = { id: randomUUID(), kind: 'partner', clientIds: [clientA] };
const siteOf = (id: string, clientId: string, projectId: string) => ({
  id,
  clientId,
  projectId,
  countryCode: 'ES',
  cityCode: 'MAD',
  cityName: 'Madrid',
  runningNo: 1,
  name: 'Site 001',
  standard: 'L' as const,
});
const cardOf = (
  clientId: string,
  siteId: string,
  version: number,
  more: Partial<typeof handoverCard.$inferInsert> = {},
) => ({
  id: randomUUID(),
  clientId,
  siteId,
  version,
  package: 'full' as const,
  ...more,
});
const itemOf = (code: string, more: Partial<typeof handoverItem.$inferInsert> = {}) => ({
  id: randomUUID(),
  clientId: clientA,
  cardId: cardA,
  code,
  status: 'provided' as const,
  ...more,
});
let testDb: TestDatabase;
let database: Database;

type Tx = Parameters<Parameters<typeof inActorTransaction>[2]>[0];
const asStaff = <T>(work: (tx: Tx) => Promise<T>) => inActorTransaction(database.db, staff, work);
const cardsVisibleTo = (actor: DbActor) =>
  inActorTransaction(database.db, actor, async (tx) => (await tx.select().from(handoverCard)).length);
const itemsVisibleTo = (actor: DbActor) =>
  inActorTransaction(database.db, actor, async (tx) => (await tx.select().from(handoverItem)).length);

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  database = createDatabase(testDb.url);
  await migrateUp(database.pool);
  await asStaff(async (tx) => {
    await tx.insert(client).values([
      { id: clientA, shortCode: 'CLIENTA', name: 'Client A' },
      { id: clientB, shortCode: 'CLIENTB', name: 'Client B' },
    ]);
    await tx
      .insert(site)
      .values([siteOf(siteA, clientA, 'CLIENTA-ES-MAD-001'), siteOf(siteB, clientB, 'CLIENTB-ES-MAD-001')]);
    await tx
      .insert(handoverCard)
      .values([
        { ...cardOf(clientA, siteA, 1), id: cardA },
        cardOf(clientB, siteB, 1, { status: 'submitted', submittedAt: new Date(), submittedBy: staff.id }),
      ]);
    await tx.insert(handoverItem).values([itemOf('A1', { value: 'PO 001, 1 Oct' }), itemOf('F1')]);
  });
});

afterAll(async () => {
  await database.close();
  await testDb.drop();
});

it('staff see every card and item', async () => {
  expect(await cardsVisibleTo(staff)).toBe(2);
  expect(await itemsVisibleTo(staff)).toBe(2);
});

it('clients and partners never see a Handover Card, not even their own', async () => {
  for (const actor of [userOfA, partnerOfA]) {
    expect(await cardsVisibleTo(actor)).toBe(0);
    expect(await itemsVisibleTo(actor)).toBe(0);
  }
  await expect(
    inActorTransaction(database.db, userOfA, (tx) =>
      tx.insert(handoverCard).values(cardOf(clientA, siteA, 9)),
    ),
  ).rejects.toThrow();
});

it("a card's client is its project's client, and an item's client is its card's", async () => {
  await expect(asStaff((tx) => tx.insert(handoverCard).values(cardOf(clientA, siteB, 2)))).rejects.toThrow();
  await expect(
    asStaff((tx) => tx.insert(handoverItem).values(itemOf('A2', { clientId: clientB }))),
  ).rejects.toThrow();
});

it('one card in play per project; a returned card is resubmitted as a new version', async () => {
  await expect(asStaff((tx) => tx.insert(handoverCard).values(cardOf(clientA, siteA, 2)))).rejects.toThrow();
  await asStaff((tx) =>
    tx
      .update(handoverCard)
      .set({ status: 'returned', submittedAt: new Date(), submittedBy: staff.id })
      .where(eq(handoverCard.id, cardA)),
  );
  await asStaff((tx) => tx.insert(handoverCard).values(cardOf(clientA, siteA, 2)));
  await expect(asStaff((tx) => tx.insert(handoverCard).values(cardOf(clientA, siteA, 2)))).rejects.toThrow();
});

it('a submitted card has a submission date and a draft has none', async () => {
  await expect(
    asStaff((tx) => tx.insert(handoverCard).values(cardOf(clientB, siteB, 3, { status: 'submitted' }))),
  ).rejects.toThrow();
});

it('N/A needs a reason (SOP-DEL-01 §6, E2 AC1)', async () => {
  await expect(
    asStaff((tx) => tx.insert(handoverItem).values(itemOf('A5', { status: 'na' }))),
  ).rejects.toThrow();
  await expect(
    asStaff((tx) => tx.insert(handoverItem).values(itemOf('A5', { status: 'na', naReason: '  ' }))),
  ).rejects.toThrow();
  await asStaff((tx) =>
    tx
      .insert(handoverItem)
      .values(itemOf('A5', { status: 'na', naReason: 'Supply-only, no warranty terms' })),
  );
});

it('group F content never sits in the card — only in the restricted Internal Notes (E2 AC7)', async () => {
  await expect(
    asStaff((tx) => tx.insert(handoverItem).values(itemOf('F2', { value: '10% discount agreed at dinner' }))),
  ).rejects.toThrow();
});

it('item codes follow the §6 checklist', async () => {
  await expect(asStaff((tx) => tx.insert(handoverItem).values(itemOf('Z1')))).rejects.toThrow();
});
